import{_ as e,H as l,f as d,b as s,j as a,i as n}from"./chunks/framework.DLd0CbzH.js";const t="/app-mockup-ru.webp",b=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"ОмниКрафт ЕРП","text":"Умная система учёта для ремесленников","tagline":"Бережливый учёт без рутины. Превращайте кожу, дерево и глину в прибыльный бизнес, а не в бухгалтерский хаос. Офлайн-доступ, точная себестоимость и честная аналитика.","image":{"src":"/logo.svg","alt":"ОмниКрафт ЕРП"},"actions":[{"theme":"brand","text":"Скачать для ОС Windows ↓","link":"https://github.com/NikMurashkin/OmniCraft-ERP-Releases/releases/latest/download/OmniCraft_ERP.exe"},{"theme":"alt","text":"Документация →","link":"/ru/docs/introduction"}]}},"headers":[],"relativePath":"ru/index.md","filePath":"ru/index.md"}'),c={name:"ru/index.md"};function o(r,i,v,p,h,u){return l(),d("div",null,[...i[0]||(i[0]=[s("div",{id:"notice-banner",class:"notice-banner"},[s("div",{class:"notice-content"},[s("span",{class:"notice-icon"},"⚠️"),s("p",null,[a(" Сайт ещё не доделан, но программа уже работает, вы можете её скачать и попробовать."),s("br"),a(" В ближайшее время мы подготовим Пользовательское соглашение и сделаем доступными покупку лицензии и всех версий программы. ")])]),s("button",{class:"notice-close",onclick:"document.getElementById('notice-banner').style.display='none'"},"×")],-1),n('<div class="glow-bg top-glow"></div><div class="custom-section showcase-section" style="padding-bottom:2rem;"><div class="section-container"><div class="showcase-wrapper"><div class="showcase-glow"></div><div class="showcase-window"><div class="window-header"><span class="dot red"></span><span class="dot yellow"></span><span class="dot green"></span></div><img src="'+t+'" alt="Интерфейс ОмниКрафт ЕРП" class="ui-screenshot"><div class="window-fade"></div></div></div></div></div><div class="custom-section section-dark-2"><div class="section-container"><div class="split-layout"><div class="split-left"><h2 class="gradient-text text-left">Эволюция вашего учёта</h2><p>Таблицы — отличный инструмент для старта. Но когда появляются десятки материалов, очередь заказов и плавающая стоимость логистики, ручной учёт начинает тормозить развитие мастерской.</p><p><strong>ОмниКрафт ЕРП</strong> — это профессиональный следующий шаг. Вы перестаете писать формулы и начинаете управлять готовыми бизнес-метриками.</p></div><div class="split-right"><div class="vs-card"><div class="vs-column bad"><div class="vs-header">Обычные Таблицы</div><ul><li><span class="icon">✕</span> Нет каскадного резервирования сырья под заказы</li><li><span class="icon">✕</span> Сложное ручное распределение цены доставки</li><li><span class="icon">✕</span> Сбитые формулы и ошибки округления</li><li><span class="icon">✕</span> Невозможность списания партий по ФИФО</li></ul></div><div class="vs-divider">VS</div><div class="vs-column good"><div class="vs-header brand">ОмниКрафт ЕРП</div><ul><li><span class="icon">✓</span> Динамический Верстак с умным дефицитом</li><li><span class="icon">✓</span> Автоматический МАК-расчет себестоимости</li><li><span class="icon">✓</span> 100% точность (целочисленная архитектура)</li><li><span class="icon">✓</span> Авто-износ станков и оборудования</li></ul></div></div></div></div></div></div><div class="custom-section section-dark-1"><div class="section-container"><div class="section-header" style="margin-bottom:2rem;"><h2 class="gradient-text">Кому идеально подойдет ОмниКрафт?</h2><p class="section-subtitle">Система спроектирована универсальной: математика себестоимости работает одинаково точно для любого физического ремесла.</p></div><div class="audience-grid"><div class="audience-card"><span class="audience-icon">👜</span><h4>Кожевенное дело</h4><p>Учет дециметров шкур, погонных метров стропы, расход клея, химии и дорогой фурнитуры.</p></div><div class="audience-card"><span class="audience-icon">🪚</span><h4>Столярные мастерские</h4><p>Учет массива дерева, листов фанеры, лакокрасочных материалов и строгая амортизация ЧПУ-станков.</p></div><div class="audience-card"><span class="audience-icon">🏺</span><h4>Керамика и Декор</h4><p>Учет килограммов глины, литров глазури, пигментов и расчет амортизации муфельных печей для обжига.</p></div><div class="audience-card"><span class="audience-icon">🧵</span><h4>Швейные студии</h4><p>Учет рулонов и метража тканей, ниток, фурнитуры и расчет стоимости нормо-часов работы швей.</p></div></div></div></div><div class="custom-section bento-section"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Всё, что нужно мастерской.<br>В единой системе.</h2><p class="section-subtitle">ОмниКрафт связывает склад, верстак и кассу в умный, непрерывный конвейер.</p></div><div class="bento-grid"><div class="bento-card"><div class="bento-bg-gradient"></div><div class="bento-icon-wrapper"><svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="4" width="16" height="16" rx="2" ry="2"></rect><line x1="9" y1="9" x2="15" y2="9"></line><line x1="9" y1="13" x2="15" y2="13"></line><line x1="9" y1="17" x2="15" y2="17"></line></svg></div><h3>Умная себестоимость (МАК)</h3><p>Программа сама усредняет стоимость сырья при закупках и честно распределяет цену доставки по материалам пропорционально их стоимости, а не поровну.</p><div class="mini-ui"><div class="mini-row"><span class="label">Кожа Buttero (Коньяк):</span><span class="val">5 000 ₽ <span class="addition">+500 ₽</span></span></div><div class="mini-row"><span class="label">Итальянские пряжки:</span><span class="val">1 000 ₽ <span class="addition">+100 ₽</span></span></div><div class="delivery-badge">Доставка партии: 600 ₽</div></div></div><div class="bento-card"><div class="bento-icon-wrapper"><svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="4" width="20" height="16" rx="2" ry="2"></rect><line x1="12" y1="4" x2="12" y2="20"></line><line x1="2" y1="12" x2="22" y2="12"></line></svg></div><h3>Смешанные финансы</h3><p>Не разделяйте искусственно личный кошелёк и кассу мастерской. Система автоматически покажет, когда ваш проект полностью окупит вложения.</p><div class="mini-ui"><div class="balance-title">Капитал бизнеса + Личные средства</div><div class="balance-bar"><div class="bar-fill positive" style="width:60%;"></div><div class="bar-fill negative" style="width:40%;"></div></div><div class="balance-labels"><span>Активы (Оборудование): 150k ₽</span><span class="neg">Сальдо ДДС: -50k ₽</span></div></div></div><div class="bento-card"><div class="bento-icon-wrapper"><svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"></path></svg></div><h3>Умный Верстак</h3><p>Планируйте очередь пошива. Программа проанализирует остатки на складе сырья и покажет дефицит ресурсов сверху вниз.</p><div class="mini-ui"><div class="queue-item"><span><span class="status-dot green"></span>Рюкзак Adler (x1)</span><span class="badge-ready">Обеспечен</span></div><div class="queue-item"><span><span class="status-dot red"></span>Сумка Bifold (x2)</span><span class="badge-deficit">Дефицит сырья</span></div></div></div><div class="bento-card"><div class="bento-icon-wrapper"><svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></div><h3>Рейтинг Time ROI (Маржинальность)</h3><p>Узнайте, сколько реальной прибыли приносит вашей мастерской один час работы над каждым конкретным изделием.</p><div class="mini-ui"><div class="roi-item"><span class="name">Обложка паспорта:</span><span class="roi-val green">1 500 ₽ / ч</span></div><div class="roi-item"><span class="name">Сложная сумка:</span><span class="roi-val muted">300 ₽ / ч</span></div></div></div><div class="bento-card span-2 highlight-card"><div class="bento-bg-gradient brand-glow"></div><div class="bento-icon-wrapper brand-text"><svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path></svg></div><h3>100% Автономность и безопасность (Локал-Фёрст)</h3><p>Локальная архитектура базы данных SQLite с режимом журналирования WAL и автоматические ротационные бэкапы (GFS) бережно защитят ваши цифры от отключений электричества и сбоев ПК. Программа не требует интернета для работы — ваши финансовые секреты остаются только на вашем компьютере.</p></div></div></div></div><div class="custom-section section-dark-1"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Единый поток: от сырья до чистой прибыли</h2></div><div class="sleek-pipeline"><div class="sleek-step"><div class="step-badge">01</div><h3>Снабжение</h3><p>Вносите активы в Мастерскую и закупаете материалы на Склад.</p><div class="step-footer">Итог: формируется капитал.</div></div><div class="sleek-step"><div class="step-badge">02</div><h3>Калькулятор</h3><p>Создаете карту изделия, задаете расходы и время.</p><div class="step-footer">Итог: расчет себестоимости.</div></div><div class="sleek-step"><div class="step-badge">03</div><h3>Производство</h3><p>Запускаете партию на Верстак и сдаете на Витрину.</p><div class="step-footer">Итог: товар с ФИФО-ценой.</div></div><div class="sleek-step"><div class="step-badge">04</div><h3>Продажи</h3><p>Пробиваете чек с учетом логистики и комиссий.</p><div class="step-footer">Итог: рост чистой прибыли.</div></div></div></div></div><div class="custom-section section-dark-2"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Экосистема ПРО-уровня</h2></div><div class="bento-grid pro-grid"><div class="bento-card span-full flex-row"><div class="card-content"><div class="bento-icon-wrapper brand-text"><svg viewBox="0 0 24 24" width="28" height="28" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 2 7 12 12 22 7 12 2 12 2"></polygon><polyline points="2 17 12 22 22 17"></polyline><polyline points="2 12 12 17 22 12"></polyline></svg></div><h3>Мультипространства (Multi-Workspaces)</h3><p>Ведете несколько направлений? (Например: кожевенное дело и продажа выкроек в ПДФ). Создавайте неограниченное количество изолированных баз данных в одном окне с мгновенным переключением и единым ЗИП-бэкапом.</p><span class="pro-tag">Доступные шаблоны: Производство. Скоро: Услуги, Торговля.</span></div></div><div class="bento-card"><div class="bento-icon-wrapper brand-text"><svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect><line x1="12" y1="8" x2="12" y2="16"></line><line x1="8" y1="12" x2="16" y2="12"></line></svg></div><h3>«Мой капитал» (Личные финансы)</h3><p>Не вбивайте каждый чек из супермаркета! Просто раз в месяц обновляйте остатки на банковских картах, а программа сама вычислит ваши повседневные траты через дельту прибыли (Пи-энд-Эл) бизнесов.</p></div><div class="bento-card"><div class="bento-icon-wrapper brand-text"><svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></div><h3>Сквозные модули (Скоро)</h3><p>Специализированные плагины (например, генерация выкроек, расчет площади шкур), которые будут работать поверх всех ваших пространств одновременно.</p></div></div></div></div><div class="custom-section section-dark-1"><div class="glow-bg center-glow"></div><div class="section-container"><div class="section-header"><h2 class="gradient-text">Выберите удобный формат</h2></div><div class="sleek-pricing"><div class="pricing-card"><div class="p-header"><h4>Free (Бесплатный)</h4><div class="p-price">0 ₽</div><p>Для старта и знакомства</p></div><ul class="p-features"><li><i></i> Все 9 рабочих вкладок</li><li><i></i> Безопасность WAL и бэкапы</li><li class="warning"><i></i> Лимит: до 20 чеков (продаж)</li><li class="disabled"><i></i> Мультипространства</li><li class="disabled"><i></i> Вкладка «Мой капитал»</li><li class="disabled"><i></i> Сквозные модули</li></ul></div><div class="pricing-card standard"><div class="p-header"><h4>Standard (Стандартный)</h4><div class="p-price">Подписка <span class="or-divider">или</span> Навсегда</div><p>Для стабильной мастерской</p></div><ul class="p-features"><li><i></i> Все 9 рабочих вкладок</li><li><i></i> Безопасность WAL и бэкапы</li><li class="active"><i></i> <b>Безлимитные продажи</b></li><li class="disabled"><i></i> Мультипространства</li><li class="disabled"><i></i> Вкладка «Мой капитал»</li><li><i></i> Сквозные модули <em>(Докупка)</em></li></ul></div><div class="pricing-card pro-card"><div class="pro-glow"></div><div class="pro-badge">Максимум</div><div class="p-header"><h4>PRO (Профессиональный)</h4><div class="p-price">Разовое расширение</div><p>Для нескольких направлений</p></div><ul class="p-features"><li><i></i> Все 9 рабочих вкладок</li><li><i></i> Безопасность WAL и бэкапы</li><li class="active"><i></i> <b>Безлимитные продажи</b></li><li class="active-pro"><i></i> <b>Мультипространства</b></li><li class="active-pro"><i></i> <b>Вкладка «Мой капитал»</b></li><li><i></i> Сквозные модули <em>(Докупка)</em></li></ul></div></div><div class="pricing-notice"><strong>💡 Важно о Free-лимите:</strong> Вы можете тестировать бесплатную версию сколько угодно (в ней нет таймера). Лимит в 20 чеков — это предохранитель. Попытка обойти его удалением старых продаж разрушит вашу историческую аналитику и балансы. Покупка лицензии — это инвестиция в сохранение чистоты цифр бизнеса. </div></div></div><div class="custom-section section-dark-2"><div class="section-container"><div class="section-header"><h2 class="gradient-text">Часто задаваемые вопросы</h2></div><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Нужен ли интернет для работы в программе?</summary><div class="faq-content"><p><strong>Нет.</strong> ОмниКрафт ЕРП — это Локал-Фёрст приложение. Оно устанавливается на ваш компьютер, и вся база данных (SQLite) хранится локально на вашем жестком диске. Вы можете полноценно работать в гараже или подвале без доступа к сети.</p></div></details><details class="faq-item"><summary class="faq-summary">Что будет, если мой компьютер сломается? Я потеряю все данные?</summary><div class="faq-content"><p>В программу встроена мощная система автоматических фоновых автосохранений (по стандарту GFS). Программа регулярно делает слепки базы (каждый день, неделю, месяц, и при каждом закрытии).</p><p>Вы можете в любой момент зайти в меню «Файл ➔ Экспорт» и выгрузить единый ЗИП-архив со всеми своими данными на флешку или в облако, чтобы в случае поломки ПК восстановить всё на новом устройстве за 10 секунд.</p></div></details><details class="faq-item"><summary class="faq-summary">Что произойдет, когда я достигну лимита в 20 продаж во Free-версии?</summary><div class="faq-content"><p>Программа перейдет в безопасный режим <strong>«Только чтение»</strong> для финальных операций. Вы больше не сможете пробивать новые чеки в POS-терминале и выпускать новые партии с Верстака.</p><p>Однако <strong>ваши данные не будут заблокированы или удалены</strong>. Вы по-прежнему сможете заходить в программу, смотреть аналитику, выгружать бэкапы и пользоваться калькулятором. Как только вы приобретете и введете лицензионный ключ в Настройках, лимит снимется мгновенно.</p></div></details><details class="faq-item"><summary class="faq-summary">Есть ли версия для Мак ОС (Mac OS) или Линукс (Linux)?</summary><div class="faq-content"><p>В данный момент мы собираем и тестируем установочный файл только для ОС Windows (10/11). </p><p>Однако архитектура ОмниКрафт ЕРП является кроссплатформенной. Базы данных абсолютно совместимы между системами. В будущем мы планируем выпустить нативные сборки для Мак ОС и Линукс.</p></div></details></div></div></div><div class="custom-section section-dark-1"><div class="section-container"><div class="sleek-about"><div class="about-quote"> «ОмниКрафт ЕРП — это не продукт безликой корпорации. Программа родилась в пыли и запахе натуральной кожи, под стук молотка и стрекот машин». </div><div class="about-text"> Создатель системы — <strong>Кожевенная мастерская Николая Мурашкина</strong>. Мы создаем физические изделия на десятилетия, и ту же философию заложили в этот код. <br><br>Программа говорит с мастером на языке рентабельности и здравого смысла, а не сложных бухгалтерских проводок. <br><br><a href="https://nmurashkin.ru" target="_blank">🌐 nmurashkin.ru →</a></div></div></div></div><div class="custom-cta-block"><div class="glow-bg bottom-glow"></div><h2 class="gradient-text">Готовы навести порядок в мастерской?</h2><p class="cta-subtitle" style="color:var(--vp-c-text-2);max-width:600px;margin:0 auto 2rem;line-height:1.6;">Быстрый старт: внесите текущие остатки кожи на склад, укажите историческое сальдо кассы — и математика сойдется в первый же день.</p><div class="cta-buttons"><a class="vp-button brand" href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases/releases/latest/download/OmniCraft_ERP.exe">⬇ Скачать для ОС Windows</a><a class="vp-button alt" href="/ru/docs/introduction">📖 Читать документацию</a></div><div class="footer-links"><a href="https://github.com/NikMurashkin/OmniCraft-ERP-Releases" target="_blank">Репозиторий на Гитхабе</a><a href="/ru/docs/licenses">Лицензии</a><a href="/ru/docs/about">О разработчике</a></div></div>',11)])])}const m=e(c,[["render",o]]);export{b as __pageData,m as default};
